<?php declare(strict_types=1); namespace App\Model\Table; use Cake\ORM\Table; use Cake\Validation\Validator; class ResidentesTable extends Table { /** Configures resident associations. */ public function initialize(array $config):void { parent::initialize($config);$this->setTable('residentes');$this->setDisplayField('full_name');$this->belongsTo('Viviendas',['foreignKey'=>'vivienda_id']); } /** Validates resident records. */ public function validationDefault(Validator $v):Validator { return $v->notEmptyString('resident_code')->maxLength('resident_code',30)->integer('vivienda_id')->notEmptyString('vivienda_id')->notEmptyString('document_type')->notEmptyString('document_number')->notEmptyString('full_name')->inList('relationship_type',['tenant','occupant','relative','household_member'])->email('email',false)->allowEmptyString('email')->date('start_date',['ymd'])->allowEmptyDate('start_date')->date('end_date',['ymd'])->allowEmptyDate('end_date'); } }
